    Bug 1979682 - Follow up: fix menuitem icons for web extensions. r=Paenglab

    Differential Revision: https://phabricator.services.mozilla.com/D259460

diff --git a/mail/base/content/webextensions.css b/mail/base/content/webextensions.css
index 2b40d534935..48252eefca5 100644
--- a/mail/base/content/webextensions.css
+++ b/mail/base/content/webextensions.css
@@ -13,7 +13,6 @@
 }

 /* for browserAction, composeAction and messageAction */
-.spaces-addon-menuitem,
 .webextension-action {
   list-style-image: var(--webextension-toolbar-image, inherit);

@@ -22,6 +21,14 @@
   }
 }

+.spaces-addon-menuitem {
+  --menuitem-icon: var(--webextension-toolbar-image, inherit);
+
+  :root[lwtheme] & {
+    --menuitem-icon: var(--webextension-toolbar-image-dark, inherit);
+  }
+}
+
 /* for buttons in sidebar or sidebar menu */
 .spaces-addon-button img {
   content: var(--webextension-toolbar-image, inherit);
@@ -32,11 +39,14 @@
 }

 @media (prefers-color-scheme: dark) {
-  :root .spaces-addon-menuitem,
   .webextension-action {
     list-style-image: var(--webextension-toolbar-image-light, inherit) !important;
   }

+  :root .spaces-addon-menuitem {
+    --menuitem-icon: var(--webextension-toolbar-image-light, inherit) !important;
+  }
+
   :root .spaces-addon-button img {
     content: var(--webextension-toolbar-image-light, inherit) !important;
   }
